"""F1 evidence: base vs new identity per corpus/mode, and missing props (checker-only names) before/after.

Usage: python3 -I compare.py   (reads base/ and new/ here)
"""
import json, os

HERE = os.path.dirname(os.path.abspath(__file__))
CORPORA = ['gate-large', 'chakra-only', 'shadcn', 'antd', 'mantine', 'spectrum', 'chakra']


def load(side, name, mode):
    d = json.load(open(f'{HERE}/{side}/{name}.{mode}.json'))
    d.pop('stats', None)
    return d


def comp_props(d, c):
    out = {}
    for sid in c['props']:
        for n, pid in d['propSets'][sid].items():
            out[n] = d['props'][pid]
    for inh in c['inheritance']:
        m = d['propSets'].get(inh['members']) if inh.get('members') else None
        for n, pid in (m or {}).items():
            out.setdefault(n, d['props'][pid])
    return out


def expand(d, c):
    """A component with its prop sets and props inlined, so ids do not matter."""
    c = dict(c)
    c['props'] = {n: p for sid in c['props'] for n, p in ((n, d['props'][pid]) for n, pid in d['propSets'][sid].items())}
    c['inheritance'] = [dict(i, members=sorted((d['propSets'].get(i['members']) or {}).keys()) if i.get('members') else None)
                        for i in c['inheritance']]
    return c


def identity(name, mode):
    b, n = load('base', name, mode), load('new', name, mode)
    changed = []
    for key in sorted(set(b['components']) | set(n['components'])):
        bc, nc = b['components'].get(key), n['components'].get(key)
        if bc is None or nc is None:
            changed.append((key, 'only in ' + ('new' if bc is None else 'base')))
            continue
        be, ne = expand(b, bc), expand(n, nc)
        if json.dumps(be, sort_keys=True) != json.dumps(ne, sort_keys=True):
            added = sorted(set(ne['props']) - set(be['props']))
            removed = sorted(set(be['props']) - set(ne['props']))
            other = sorted(k for k in set(be) | set(ne) if k != 'props' and be.get(k) != ne.get(k))
            retyped = sorted(p for p in set(be['props']) & set(ne['props']) if be['props'][p] != ne['props'][p])
            changed.append((key, f'+{added} -{removed} retyped={retyped} other={other}'))
    rest_b = {k: v for k, v in b.items() if k not in ('components', 'props', 'propSets')}
    rest_n = {k: v for k, v in n.items() if k not in ('components', 'props', 'propSets')}
    top = sorted(k for k in set(rest_b) | set(rest_n) if json.dumps(rest_b.get(k), sort_keys=True) != json.dumps(rest_n.get(k), sort_keys=True))
    return changed, top


def missing(side, name):
    ch, st = load('new', name, 'checker'), load(side, name, 'struct')
    rows = {}
    for key, cc in ch['components'].items():
        sc = st['components'].get(key)
        if sc is None:
            continue
        miss = sorted(set(comp_props(ch, cc)) - set(comp_props(st, sc)))
        if miss:
            rows[key] = miss
    return rows


for name in CORPORA:
    for mode in ('struct', 'checker'):
        changed, top = identity(name, mode)
        print(f'{name} {mode}: {len(changed)} components differ; top-level keys differ: {top}')
        for key, what in changed:
            print('   ', key, what)
for name in ('chakra', 'spectrum'):
    before, after = missing('base', name), missing('new', name)
    print(f'{name} missing (checker new vs struct): before {len(before)} comps / {sum(map(len, before.values()))} props;'
          f' after {len(after)} comps / {sum(map(len, after.values()))} props')
    for key in sorted(set(before) | set(after)):
        if before.get(key) != after.get(key):
            print('   ', key, 'before', before.get(key, [])[:8], len(before.get(key, [])), 'after', after.get(key, [])[:8], len(after.get(key, [])))

